import { PrismaClient } from '@prisma/client'
const prisma = new PrismaClient()

export async function transfer(fromId: number, toId: number, amount: number) {
  return prisma.$transaction(async (tx) => {
    await tx.{{model_a}}.update({ where: { id: fromId }, data: { balance: { decrement: amount } } })
    await tx.{{model_b}}.update({ where: { id: toId }, data: { balance: { increment: amount } } })
  })
}
